def _ngrams(text, n):
    w = text.lower().split()
    return [tuple(w[i:i + n]) for i in range(len(w) - n + 1)]

def contamination(test_items, corpus, n=8, threshold=0.5):
    seen = set()
    for doc in corpus:
        seen.update(_ngrams(doc, n))
    flagged = []
    for idx, item in enumerate(test_items):
        grams = _ngrams(item, n)
        if grams and sum(g in seen for g in grams) / len(grams) >= threshold:
            flagged.append(idx)
    return flagged
